pub const IdsRequestKind = enum {
    workspace,
    screen,
    pane,
    surface,

    pub fn fromWire(value: []const u8) !@This() {
        if (std.mem.eql(u8, value, "workspace")) return .workspace;
        if (std.mem.eql(u8, value, "screen")) return .screen;
        if (std.mem.eql(u8, value, "pane")) return .pane;
        if (std.mem.eql(u8, value, "surface")) return .surface;
        return error.UnknownEnumValue;
    }

    pub fn toWire(self: @This()) []const u8 {
        return switch (self) {
            .workspace => "workspace",
            .screen => "screen",
            .pane => "pane",
            .surface => "surface",
        };
    }
};

